                    }
                    else
                    {
                        @step
                    }
                </span>
                <span class="step-label">@label</span>
            </button>

            @if (i < _stepLabels.Length - 1)
            {
                <span class="step-connector @(step < _currentStep ? "done" : "")"></span>
