                <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
            </div>
        </section>
    }

    @* ───── Step 4: Cover Letter ───── *@
    @if (_currentStep == 4)
    {
        <section>
            <h4>Cover Letter</h4>

            <div class="mb-2">
