            </div>
            <div class="text-muted mb-3">@(_coverLetter?.Length ?? 0) / 2000 characters</div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next</button>
            </div>
        </section>
    }

    @* ───── Step 5: Review & Submit ───── *@
    @if (_currentStep == 5)
    {
        <section>
            <h4>Review &amp; Submit</h4>

            @if (_submitted)
            {
                <div class="alert alert-success">
                    <h5>Application Submitted!</h5>
                    <p>Your application has been received. Your confirmation number is <strong>#@_applicationId</strong>.</p>
                </div>
            }
            else
            {
                @* Personal Info *@
                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>Personal Information</strong>
                        <button class="btn btn-link btn-sm p-0" @onclick='() => GoToStep(1)'>Edit</button>
                    </div>
                    <div class="card-body">
                        <dl class="row mb-0">
                            <dt class="col-sm-3">Full Name</dt><dd class="col-sm-9">@_fullName</dd>
                            <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                            <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                            <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                        </dl>
                    </div>
                </div>

                @* Work History *@
                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>Work History</strong>
                        <button class="btn btn-link btn-sm p-0" @onclick='() => GoToStep(2)'>Edit</button>
                    </div>
                    <div class="card-body">
                        @foreach (var entry in _workEntries)
                        {
                            <div class="mb-3">
                                <strong>@entry.Title</strong> at @entry.Company<br />
                                <span class="text-muted">
                                    @entry.StartDate.ToString("MMM yyyy") &ndash;
                                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                                </span>
                                @if (!string.IsNullOrWhiteSpace(entry.Description))
                                {
                                    <p class="mt-1 mb-0">@entry.Description</p>
                                }
                            </div>
                        }
                    </div>
                </div>

                @* References *@
                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>References</strong>
                        <button class="btn btn-link btn-sm p-0" @onclick='() => GoToStep(3)'>Edit</button>
                    </div>
                    <div class="card-body">
                        @foreach (var r in _references)
                        {
                            <div class="mb-2">
                                <strong>@r.Name</strong> — @r.Relationship<br />
                                <span class="text-muted">@r.Email &middot; @r.Phone</span>
                            </div>
                        }
                    </div>
                </div>

                @* Cover Letter *@
                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>Cover Letter</strong>
                        <button class="btn btn-link btn-sm p-0" @onclick='() => GoToStep(4)'>Edit</button>
                    </div>
                    <div class="card-body">
                        <p style="white-space: pre-wrap;">@_coverLetter</p>
                    </div>
                </div>

                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_loading">
                        @if (_loading) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Submit Application
                    </button>
                </div>
            }
        </section>
    }
</div>

@code {
    private static readonly string[] _stepLabels =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int _currentStep = 1;
    private bool _loading;
    private bool _submitted;
    private int _applicationId;
    private string? _errorMessage;

    // Step 1
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2
    private List<WorkEntryModel> _workEntries = [new()];

    // Step 3
    private List<ReferenceModel> _references = [new(), new()];

    // Step 4
    private string _coverLetter = "";

    // ───── Navigation ─────

    private void GoToStep(int step)
    {
        if (step < _currentStep && !_submitted)
        {
            _errorMessage = null;
            _currentStep = step;
        }
    }

    private void NextStep()
    {
        _errorMessage = null;
        _currentStep++;
    }

    private void PreviousStep()
    {
        _errorMessage = null;
        _currentStep--;
    }

    // ───── Step 1 validation ─────

    private async Task NextFromPersonalInfo()
    {
        _errorMessage = null;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email)
            || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        _loading = true;
        try
        {
            var valid = await ApplicationService.ValidateEmailAsync(_email);
            if (!valid)
            {
                _errorMessage = "Please enter a valid email address.";
                return;
            }
            _currentStep = 2;
        }
        finally
        {
            _loading = false;
        }
    }

    // ───── Step 2 ─────

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index) => _workEntries.RemoveAt(index);

    private void NextFromWorkHistory()
    {
        _errorMessage = null;

        foreach (var e in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title)
                || e.StartDate == default)
            {
                _errorMessage = "Please fill in company, title, and start date for every position.";
                return;
            }
        }
        _currentStep = 3;
    }

    // ───── Step 3 ─────

    private void AddReference()
    {
        if (_references.Count < 3) _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index) => _references.RemoveAt(index);

    private void NextFromReferences()
    {
        _errorMessage = null;

        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _errorMessage = "Please fill in all fields for every reference.";
                return;
            }
        }
        _currentStep = 4;
    }

    // ───── Submit ─────

    private async Task SubmitApplication()
    {
        _loading = true;
        _errorMessage = null;

        try
        {
            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
            var work = new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description ?? "")).ToList());
            var refs = _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(personal, work, refs, _coverLetter);
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    // ───── Mutable view-models for two-way binding ─────

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string? Description { get; set; }
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

